        var n = Math.max(fn.orbitTotal, 1);
        var orbitR = 28 + Math.min(n, 24) * 2.2;
        var angle = (fn.orbitIndex / n) * Math.PI * 2;
        fn.x = parent.x + Math.cos(angle) * orbitR;
        fn.y = parent.y + Math.sin(angle) * orbitR;
